import * as T from './vendor/three.module.js';
import {crops} from './life-state.js';
export function createLeisure({outdoor,avatar,body,legs,arms,place,box,ball,cylinder,line,group,tag,interactive,table}){
 function plant(parent,type){const c=crops[type],g=group(parent);cylinder(g,0x638c50,0,.13,0,.012,.016,.26,7);for(const s of [-1,1]){const leaf=ball(g,0x739b57,s*.05,.13,0,.055,9);leaf.scale.set(.07,.018,.03);leaf.rotation.z=s*.4}
 if(c.flower){ball(g,type==='sunflower'?0x8d653d:c.color,0,.3,0,.045,12);for(let i=0;i<7;i++){const a=i*Math.PI*2/7,p=ball(g,c.color,Math.cos(a)*.065,.3,Math.sin(a)*.065,.045,10);p.scale.y=.42}}
 else{const fruit=ball(g,c.color,0,.12,.035,.085,12);if(type==='carrot')fruit.scale.set(.7,1.5,.7);if(type==='strawberry'){fruit.scale.set(.8,.85,.8);for(let i=0;i<5;i++)ball(g,0xf6da98,Math.sin(i*2.4)*.055,.1+i*.012,.096,.006,6)}}g.traverse(m=>{if(m.isMesh)m.geometry=m.geometry.clone()});return g}
 const garden=place(outdoor,.63,.08),beds=[],plants=[];for(let i=0;i<6;i++){const x=(i%3-1)*.48,z=(Math.floor(i/3)-.5)*.55,g=group(garden,x,0,z);box(g,0xb19166,0,.055,0,.44,.11,.49);box(g,0x786447,0,.114,0,.38,.02,.43);beds.push(g)}
 interactive('garden',.63,.08,.8,.63,.32);
 const court=place(outdoor,1.6,-.55);box(court,0xb5a785,0,-.08,0,2.75,.27,2.95);box(court,0x87a89a,0,.061,0,2.66,.02,2.86);
 for(const x of [-1.24,1.24])box(court,0xf6ecce,x,.075,0,.025,.008,2.65);for(const z of [-1.31,1.31])box(court,0xf6ecce,0,.075,z,2.48,.008,.025);
 for(const x of [-.57,.57])box(court,0xf6ecce,x,.078,-.76,.022,.009,1.12);box(court,0xf6ecce,0,.078,-.2,1.16,.009,.022);
 const arc=new T.Line(new T.BufferGeometry().setFromPoints(Array.from({length:45},(_,i)=>{const a=i/44*Math.PI;return new T.Vector3(Math.cos(a)*1.05,.08,-.75+Math.sin(a)*1.05)})),new T.LineBasicMaterial({color:0xf6ecce}));court.add(arc);
 cylinder(court,0x74846e,0,1.04,-1.36,.035,.055,2,10);box(court,0xe5dfc6,0,1.92,-1.31,1.02,.66,.07);box(court,0xa58e6a,0,1.88,-1.264,.41,.28,.016);box(court,0xeee5c9,0,1.88,-1.25,.34,.21,.016);
 const ring=new T.Mesh(new T.TorusGeometry(.17,.014,8,32),new T.MeshStandardMaterial({color:0xbc7853}));ring.rotation.x=Math.PI/2;ring.position.set(0,1.7,-1.05);court.add(ring);
 for(let i=0;i<10;i++){const a=i/10*Math.PI*2;line(court,0xf0e5c9,new T.Vector3(Math.cos(a)*.17,1.7,-1.05+Math.sin(a)*.17),new T.Vector3(Math.cos(a)*.1,1.43,-1.05+Math.sin(a)*.1),.005)}
 const basketball=ball(court,0xcf864a,.4,.2,.75,.12,22);for(const a of [0,Math.PI/2]){const seam=new T.Mesh(new T.TorusGeometry(1.008,.033,5,28),new T.MeshStandardMaterial({color:0x705038}));seam.rotation.y=a;basketball.add(seam)}
 interactive('basketball',1.6,-.55,1.4,1.6,-.17);
 const vase=group(table,-.06,.67,-.31);cylinder(vase,0x9ebeb2,0,.12,0,.075,.11,.24,20);cylinder(vase,0xe1e6ca,0,.244,0,.073,.073,.016,20);const bouquet=group(vase,0,.18,0);tag(vase,'vase');
 let active=false,shot=null,world=0,data=[],plotKey='',vaseKey='';
 function disposePlant(g){g.traverse(m=>{if(m.isMesh){m.geometry.dispose()}});g.removeFromParent()}
 function update(w,worlds){world=w;data=worlds;garden.visible=w===0;court.visible=w===1;const plots=worlds[0]?.life?.plots||[];const key=JSON.stringify(plots.map(p=>p?.crop||null));if(key!==plotKey){plants.forEach(g=>g&&disposePlant(g));plants.length=0;plots.forEach((p,i)=>{plants[i]=p?plant(beds[i],p.crop):null;if(plants[i])plants[i].position.y=.13});plotKey=key}
 const flowers=worlds[w]?.life?.vase||[],vk=flowers.join(',');if(vk!==vaseKey){for(const g of [...bouquet.children])disposePlant(g);flowers.forEach((type,i)=>{const g=plant(bouquet,type),a=i*2.4;g.position.set(Math.cos(a)*.04,0,Math.sin(a)*.04);g.rotation.z=Math.sin(a)*.25});vaseKey=vk}
 }
 return {update,get active(){return active},start(){if(world!==1)return false;active=true;shot=null;court.add(avatar);avatar.position.set(0,.072,.8);avatar.rotation.set(0,Math.PI,0);legs.forEach(g=>g.rotation.x=0);arms.forEach(g=>g.rotation.x=0);body.position.y=.005;return true},stop(){if(!active)return;active=false;shot=null;outdoor.add(avatar);avatar.quaternion.identity();arms.forEach(g=>g.rotation.set(0,0,0));basketball.position.set(.4,.2,.75)},shoot(power){if(!active||shot)return null;const made=Math.abs(power-.5)<.19;shot={t:0,made,start:basketball.position.clone()};return {made}},tick(dt,t){const plots=data[0]?.life?.plots||[];plots.forEach((p,i)=>{if(p&&plants[i]){const fraction=T.MathUtils.clamp((Date.now()-p.plantedAt)/Math.max(1,p.readyAt-p.plantedAt),0,1);plants[i].scale.setScalar(.16+.84*fraction)}});if(!active)return;if(shot){shot.t+=dt;const u=Math.min(1,shot.t/1.1),end=new T.Vector3(shot.made?0:.42,1.7,-1.05);basketball.position.lerpVectors(shot.start,end,u);basketball.position.y+=Math.sin(u*Math.PI)*1.2;arms.forEach(g=>g.rotation.x=-1.8*(1-u));if(shot.t>1.1)basketball.position.y=1.7-(shot.t-1.1)*2.8;if(shot.t>1.7)shot=null}else{basketball.position.set(.39,.2+Math.abs(Math.sin(t*5))*.55,.83);arms[0].rotation.x=-.45+Math.sin(t*5)*.2}},focus(){if(!active)return null;return court.localToWorld(new T.Vector3(0,.15,.15))},state(){return {basketball:active,shooting:!!shot,court:world===1,garden:world===0}}};
}
